fn main() {
    println!("cargo:rerun-if-changed=build.rs");

    for &cluster in ALL_CLUSTERS {
        println!("cargo:rustc-check-cfg=cfg(cluster_{cluster})");
        println!(
            "cargo:rerun-if-env-changed={CLUSTER_ENV_PREFIX}{}",
            cluster.to_ascii_uppercase()
        );
    }

    let mut enabled: BTreeSet<String> = BTreeSet::new();

    for &(feat_env, clusters) in FEATURE_TO_CLUSTERS {
        if env::var_os(feat_env).is_some() {
            enabled.extend(clusters.iter().map(|&c| c.to_owned()));
        }
    }

    for (key, val) in env::vars() {
        if let Some(suffix) = key.strip_prefix(CLUSTER_ENV_PREFIX)
            && !suffix.is_empty()
        {
            let cluster = suffix.to_ascii_lowercase();
            let is_known = ALL_CLUSTERS.contains(&cluster.as_str());
            if !is_known {
                println!("cargo:rerun-if-env-changed={key}");
            }
            if is_val_enabled(&val) {
                if is_known {
                    enabled.insert(format!("cluster_{cluster}"));
                } else {
                    println!(
                        "cargo:warning=unknown Matter cluster environment variable `{key}` (no `cluster_{cluster}` in \
                         matter-spec)"
                    );
                }
            }
        }
    }

    for cluster_cfg in enabled {
        println!("cargo:rustc-cfg={cluster_cfg}");
    }
}

fn is_val_enabled(val: &str) -> bool {
    !val.is_empty() && val != "0" && !val.eq_ignore_ascii_case("false")
}
